import math
from typing import List, Tuple, Union

def f(inputs: List[Tuple[float, float, int, List[Tuple[int, int]]]]) -> Union[List[str], None]:
    for L, R, N, points in inputs:
        if L == 0 and R == 0 and N == 0:
            break
        points.sort(key=lambda x: x[0])
        max_x = points[-1][0] + L
        for x in range(math.ceil(points[0][0] / R) * R, math.floor(max_x / R) * R + 1, R):
            min_y = math.inf
            for px, py in points:
                if x - L <= px < x + L:
                    min_y = min(min_y, py)
            if min_y == math.inf:
                continue
            min_y = min_y - L + 1
            max_y = min_y + (L << 1)
            print(f'{x} {min_y} {max_y}')
    return None
```

